<?php /* Listado de solicitudes de cita urgente (CU21, CU22). */ ?>
<div class="page-heading"><div><span class="eyebrow">SOLICITUDES DE ATENCIÓN</span><h1>Citas urgentes</h1><p><?= $user['rol']==='paciente' ? 'Consulta tus solicitudes y la gestión registrada por recepción.' : 'Revisa las solicitudes pendientes y coordina su atención.' ?></p></div>
<?php if ($user['rol']==='paciente'): ?><a class="button primary" href="/urgencias/nueva">Nueva solicitud</a><?php endif; ?></div>
<section class="card"><form class="search-form" method="get" action="/urgencias"><label class="grow">Estado<select name="estado"><?php foreach (['todas'=>'Todas','pendiente'=>'Pendiente de revisión','gestionada'=>'Cita asignada','cerrada'=>'Cerrada sin cita'] as $value=>$label): ?><option value="<?= e($value) ?>" <?= $state===$value ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><button class="button secondary align-end" type="submit">Consultar</button></form>
<div class="table-scroll"><table><thead><tr><th scope="col">Código</th><th scope="col">Fecha de solicitud</th><?php if ($user['rol']!=='paciente'): ?><th scope="col">Paciente</th><?php endif; ?><th scope="col">Estado</th><th scope="col">Detalle</th></tr></thead><tbody>
<?php foreach ($listing['items'] as $item): ?><tr><td><?= e(App\UrgentService::code((int) $item['id'])) ?></td><td><?= e(clinic_datetime($item['creado_en'])) ?></td><?php if ($user['rol']!=='paciente'): ?><td><?= e($item['paciente']) ?></td><?php endif; ?><td><?= e(['pendiente'=>'Pendiente de revisión','gestionada'=>'Cita asignada','cerrada'=>'Cerrada sin cita'][$item['estado']]) ?></td><td><a class="table-action" href="/urgencias/<?= (int) $item['id'] ?>"><?= $user['rol']==='paciente' ? 'Ver solicitud' : 'Revisar y gestionar' ?></a></td></tr><?php endforeach; ?>
<?php if (!$listing['items']): ?><tr><td colspan="5" class="empty-state">No hay solicitudes con este estado.</td></tr><?php endif; ?></tbody></table></div><?php require BASE_PATH . '/views/_appointment_pagination.php'; ?></section>
